<script setup lang="ts">
import { useRoute } from 'vue-router';
import DashboardFooter from '@/components/DashboardFooter.vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import { computed, onMounted, reactive, ref } from 'vue'; import ApiAlert from '@/components/ApiAlert.vue'; import { api, errorMessage } from '@/api/client'; import { useAuth } from '@/stores/auth'; import type { ApiResponse, DocumentRequest, RequestType, AlumniProfile } from '@/types/api';
const route = useRoute();
const memberProfile = ref<AlumniProfile | null>(null);
const requestedType = typeof route.query.type === 'string' && ['CERTIFICATE', 'TRANSCRIPT', 'DIPLOMA', 'WAEC_CERTIFICATE', 'WASSCE_CERTIFICATE'].includes(route.query.type) ? route.query.type as RequestType : '';
const { user } = useAuth(); const form = reactive<{ requestType: RequestType | ''; fullNameAtGraduation: string; graduationYear: string; studentIdOrIndexNumber: string; contactPhone: string; purpose: string }>({ requestType: requestedType, fullNameAtGraduation: '', graduationYear: '', studentIdOrIndexNumber: '', contactPhone: '', purpose: '' }); const busy = ref(false); const error = ref(''); const success = ref(''); const requestId = ref(''); const initials = computed(() => (user.value?.email || 'GD').split(/[ @.]+/).filter(Boolean).slice(0, 2).map((v) => v[0]).join('').toUpperCase());
async function submit() { if (!form.requestType) { error.value = 'Select the document you need.'; return; } busy.value = true; error.value = ''; success.value = ''; try { const response = await api.post<ApiResponse<DocumentRequest>>('/requests', { ...form, graduationYear: form.graduationYear ? Number(form.graduationYear) : undefined, studentIdOrIndexNumber: form.studentIdOrIndexNumber || undefined }); requestId.value = response.data.data.id; success.value = `${response.data.message} Your reference is ${response.data.data.id}.`; Object.assign(form, { requestType: '', fullNameAtGraduation: '', graduationYear: '', studentIdOrIndexNumber: '', contactPhone: '', purpose: '' }); } catch (caught) { error.value = errorMessage(caught); } finally { busy.value = false; } }
onMounted(async () => {
 if (user.value?.role !== 'ALUMNI') return;
 try {
  const profile = (await api.get<ApiResponse<AlumniProfile>>('/alumni/profile')).data.data;
  memberProfile.value = profile;
  if (success.value) return;
  if (!form.fullNameAtGraduation) form.fullNameAtGraduation = profile.fullName;
  if (!form.graduationYear && profile.graduationYear) form.graduationYear = String(profile.graduationYear);
  if (!form.contactPhone) form.contactPhone = profile.phone || '';
 } catch { /* Profile prefill is optional; manual request entry remains available. */ }
});
</script>
<template><DashboardLayout><div class="request-reference"><header class="sticky top-0 z-40 flex items-center justify-between border-b border-slate-200 bg-white px-5 py-6 lg:px-8"><div><h1 class="text-2xl font-semibold text-primary">Document Request Form</h1><p class="mt-1 text-xs text-secondary">Official Alumni Records Department — Ministry of National Defense</p></div><div class="flex items-center gap-4"><div class="hidden text-right sm:block"><p class="text-sm font-semibold">{{ memberProfile?.fullName || user?.email || 'Member' }}</p><p class="text-[11px] text-secondary">{{ user?.role === 'ADMIN' ? 'School administrator' : memberProfile?.graduationYear ? `Class of ${memberProfile.graduationYear}` : 'Alumni Member' }}</p></div><div class="flex h-10 w-10 items-center justify-center overflow-hidden rounded-full border border-outline-variant bg-surface-container-high text-xs font-bold text-secondary"><img v-if="memberProfile?.profileImage || user?.profileImage" :src="memberProfile?.profileImage || user?.profileImage || undefined" alt="" class="h-full w-full object-cover" referrerpolicy="no-referrer"><span v-else>{{ initials }}</span></div></div></header><div class="mx-auto max-w-6xl p-5 lg:p-8"><div class="grid grid-cols-1 gap-8 lg:grid-cols-3"><div class="space-y-6 lg:col-span-2"><section class="rounded-lg border border-slate-200 bg-white p-8 shadow-sm"><form class="space-y-6" @submit.prevent="submit"><ApiAlert :message="error"/><ApiAlert :message="success" kind="success"/><RouterLink v-if="requestId" :to="{ path: '/requests', query: { request: requestId } }" class="inline-flex items-center gap-2 text-sm font-semibold text-primary underline">View submitted request<span aria-hidden="true" class="material-symbols-outlined text-sm">arrow_forward</span></RouterLink><div class="grid grid-cols-1 gap-6 md:grid-cols-2"><div class="md:col-span-2"><label for="new-requestType" class="field-label">Request Type</label><select id="new-requestType" v-model="form.requestType" class="field-input" required><option value="">Select document type...</option><option value="CERTIFICATE">Certificate</option><option value="TRANSCRIPT">Transcript</option><option value="DIPLOMA">Diploma</option><option value="WAEC_CERTIFICATE">WAEC Certificate</option><option value="WASSCE_CERTIFICATE">WASSCE Certificate</option></select></div><div class="md:col-span-2"><label for="new-fullNameAtGraduation" class="field-label">Full Name at Graduation</label><input minlength="2" maxlength="150" id="new-fullNameAtGraduation" v-model.trim="form.fullNameAtGraduation" class="field-input" placeholder="As it appears on school records" required></div><div><label for="new-graduationYear" class="field-label">Graduation Year</label><input min="1900" :max="new Date().getFullYear()" id="new-graduationYear" v-model="form.graduationYear" class="field-input" placeholder="YYYY" type="number"></div><div><label for="new-studentIdOrIndexNumber" class="field-label">Student ID / Index Number</label><input minlength="2" maxlength="100" id="new-studentIdOrIndexNumber" v-model.trim="form.studentIdOrIndexNumber" class="field-input" placeholder="e.g. GDA-0000"></div><div class="md:col-span-2"><label for="new-contactPhone" class="field-label">Contact Phone</label><input minlength="6" maxlength="30" id="new-contactPhone" v-model.trim="form.contactPhone" class="field-input" placeholder="+231 ..." type="tel" required></div><div class="md:col-span-2"><label for="new-purpose" class="field-label">Purpose of Request</label><textarea minlength="3" maxlength="1000" id="new-purpose" v-model.trim="form.purpose" class="field-input" placeholder="Explain the intended use of this document (e.g., Employment, University Admission)" rows="4" required></textarea></div></div><div class="pt-4"><button class="flex w-full items-center justify-center gap-2 rounded-lg bg-primary-container py-4 text-sm font-semibold text-white shadow-md transition hover:opacity-90" :disabled="busy"><span aria-hidden="true" class="material-symbols-outlined">send</span>{{ busy ? 'Submitting…' : 'Submit Document Request' }}</button><p class="mt-4 text-center text-[11px] italic uppercase tracking-wider text-secondary">All requests are subject to verification by the Ministry of Defense.</p></div></form></section></div><aside class="space-y-6"><section class="rounded-lg bg-primary-container p-6 text-white shadow-sm"><div class="mb-4 flex items-center gap-3"><span aria-hidden="true" class="material-symbols-outlined text-tertiary-fixed-dim">info</span><h3 class="text-lg font-semibold">Before requesting documents</h3></div><ul class="space-y-4 text-sm leading-relaxed text-slate-200"><li v-for="item in ['Confirm identification requirements with the Records Office','Have your graduation year and student/index number available','Check any applicable fees directly with the Records Office','Wait for a ready-for-pickup status before visiting']" :key="item" class="flex gap-3"><span aria-hidden="true" class="material-symbols-outlined text-sm">check_circle</span>{{ item }}</li></ul></section><section class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><h3 class="mb-3 text-sm font-semibold text-primary">Processing Timeline</h3><div class="flex items-center gap-4 border-b border-slate-50 py-3"><span aria-hidden="true" class="material-symbols-outlined text-secondary">timer</span><div><p class="text-[13px] font-semibold">Standard Processing</p><p class="text-xs text-secondary">Timing varies; check your request status and registrar notes.</p></div></div><div class="flex items-center gap-4 py-3"><span aria-hidden="true" class="material-symbols-outlined text-secondary">verified_user</span><div><p class="text-[13px] font-semibold">Verification Window</p><p class="text-xs text-secondary">Check registrar notes for collection arrangements</p></div></div></section><section class="rounded-lg border border-dashed border-outline-variant bg-surface-container-low p-6"><p class="mb-1 text-sm font-semibold">Need Assistance?</p><p class="mb-4 text-xs text-secondary">Visit the Records Office at Gray D. Allison High School Compound.</p><RouterLink to="/help" class="inline-block text-sm underline">Portal help and Records Office guidance</RouterLink></section></aside></div></div><div class="px-5 lg:px-8"><DashboardFooter/></div></div></DashboardLayout></template>
